use vstd::prelude::*;

verus! {
    // Function to check if a single number is even
    spec fn is_even(n: nat) -> bool
        decreases n,
    {
        n % 2 == 0
    }

    // Function to execute the even check for a single number
    fn is_even_exec(n: u32) -> (result: bool)
        requires
            n as nat < 0x1_0000_0000,
        ensures
            result == is_even(n as nat),
    {
        is_even(n)
    }

    // Function to check if there is at least one even number in the array
    fn is_product_even(arr: &Vec<u32>) -> (result: bool)
        requires
            arr.len() < 0x1_0000_0000,
        ensures
            result == (arr.iter().any(|&num| is_even(num as nat))),
    {
        let mut found_even: bool = false;
        let mut idx: usize = 0;

        while idx < arr.len()
            invariant
                idx <= arr.len(),
                found_even == (0..idx).any(|i| is_even(arr[i] as nat)),
            decreases arr.len() - idx,
        {
            if is_even(arr[idx] as nat) {
                found_even = true; // Found an even number
                return true; // Early return if an even number is found
            }
            idx += 1;
        }
        false // No even number found
    }
}

fn main() {
    let numbers = vec![1, 3, 5, 7];
    println!("{}", is_product_even(&numbers)); // Output: false

    let numbers_with_even = vec![1, 2, 3, 4];
    println!("{}", is_product_even(&numbers_with_even)); // Output: true

    let empty_numbers: Vec<u32> = vec![];
    println!("{}", is_product_even(&empty_numbers)); // Output: false
}